import torch


def _get_special_token_ids(tokenizer):
    im_start_ids = tokenizer.encode("<|im_start|>", add_special_tokens=False)
    im_end_ids = tokenizer.encode("<|im_end|>", add_special_tokens=False)
    assert len(im_start_ids) == 1, f"Expected <|im_start|> to be a single token, got {im_start_ids}"
    assert len(im_end_ids) == 1, f"Expected <|im_end|> to be a single token, got {im_end_ids}"
    return im_start_ids[0], im_end_ids[0]


def _find_all_positions(input_ids, token_id):
    if isinstance(input_ids, torch.Tensor):
        return (input_ids == token_id).nonzero(as_tuple=True)[0].tolist()
    return [i for i, t in enumerate(input_ids) if t == token_id]


def detect_turn_boundaries(input_ids: torch.Tensor, tokenizer) -> dict:
    if input_ids.dim() != 1:
        raise ValueError(f"Expected 1D input_ids, got shape {input_ids.shape}")

    seq_len = input_ids.size(0)
    im_start_id, im_end_id = _get_special_token_ids(tokenizer)
    ids_list = input_ids.tolist()

    im_start_positions = _find_all_positions(ids_list, im_start_id)
    im_end_positions = _find_all_positions(ids_list, im_end_id)

    newline_id = tokenizer.encode("\n", add_special_tokens=False)
    newline_id = newline_id[0] if len(newline_id) == 1 else None

    turns = []
    for i, start_pos in enumerate(im_start_positions):
        end_pos = im_end_positions[i] if i < len(im_end_positions) else seq_len - 1

        role_token_pos = start_pos + 1
        role_str = None
        content_start = role_token_pos

        scan_end = min(start_pos + 10, end_pos)
        for j in range(role_token_pos, scan_end):
            if newline_id is not None and ids_list[j] == newline_id:
                role_tokens = ids_list[role_token_pos:j]
                role_str = tokenizer.decode(role_tokens).strip()
                content_start = j + 1
                break

        if role_str is None:
            partial = tokenizer.decode(ids_list[role_token_pos:scan_end]).strip()
            for r in ("system", "user", "assistant"):
                if partial.startswith(r):
                    role_str = r
                    break
            if role_str is None:
                role_str = "unknown"
            content_start = role_token_pos + len(tokenizer.encode(role_str, add_special_tokens=False)) + 1

        content_start = min(content_start, end_pos)

        turns.append({
            "role": role_str,
            "start": start_pos,
            "end": end_pos,
            "content_start": content_start,
            "content_end": end_pos,
        })

    goal_token_positions = []
    first_user_found = False
    for turn in turns:
        if turn["role"] == "system":
            goal_token_positions.extend(range(turn["content_start"], turn["content_end"]))
        elif turn["role"] == "user" and not first_user_found:
            goal_token_positions.extend(range(turn["content_start"], turn["content_end"]))
            first_user_found = True

    assistant_last_token_positions = []
    for turn in turns:
        if turn["role"] == "assistant" and turn["content_end"] > turn["content_start"]:
            assistant_last_token_positions.append(turn["content_end"] - 1)

    boundary_positions = set()
    for pos in im_start_positions:
        boundary_positions.add(pos)
    for pos in im_end_positions:
        boundary_positions.add(pos)

    turn_distance_map = torch.zeros(seq_len, dtype=torch.long)
    dist = 0
    for i in range(seq_len):
        if i in boundary_positions:
            dist = 0
        turn_distance_map[i] = dist
        dist += 1

    turn_index_map = torch.zeros(seq_len, dtype=torch.long)
    current_turn = 0
    in_turn = False
    for i in range(seq_len):
        if ids_list[i] == im_start_id:
            if in_turn:
                current_turn += 1
            in_turn = True
        turn_index_map[i] = current_turn

    return {
        "turns": turns,
        "goal_token_positions": goal_token_positions,
        "assistant_last_token_positions": assistant_last_token_positions,
        "turn_distance_map": turn_distance_map,
        "turn_index_map": turn_index_map,
    }


def build_turn_features(input_ids: torch.Tensor, tokenizer) -> dict:
    if input_ids.dim() != 1:
        raise ValueError(f"Expected 1D input_ids, got shape {input_ids.shape}")

    seq_len = input_ids.size(0)
    im_start_id, im_end_id = _get_special_token_ids(tokenizer)
    ids_list = input_ids.tolist()

    boundary_set = set()
    for i, tid in enumerate(ids_list):
        if tid == im_start_id or tid == im_end_id:
            boundary_set.add(i)

    turn_distance = torch.zeros(seq_len, dtype=torch.long)
    dist = 0
    for i in range(seq_len):
        if i in boundary_set:
            dist = 0
        turn_distance[i] = dist
        dist += 1

    turn_index = torch.zeros(seq_len, dtype=torch.long)
    current_turn = 0
    started = False
    for i in range(seq_len):
        if ids_list[i] == im_start_id:
            if started:
                current_turn += 1
            started = True
        turn_index[i] = current_turn

    is_turn_boundary = torch.zeros(seq_len, dtype=torch.bool)
    for pos in boundary_set:
        is_turn_boundary[pos] = True

    return {
        "turn_distance": turn_distance,
        "turn_index": turn_index,
        "is_turn_boundary": is_turn_boundary,
    }

# Goal-Attention Ratio (GAR) measurement using model-native attention weights.
# Uses output_attentions=True to capture post-RoPE, post-softmax attention weights
# directly from the model, avoiding manual Q/K computation that misses RoPE.

import warnings
from contextlib import contextmanager

import torch
import torch.nn.functional as F
import numpy as np


class GARMeasurer:
    def __init__(self, model, measure_only=True):
        self.model = model
        self.measure_only = measure_only
        self._hooks = []
        self._attention_weights = {}
        self._active = False

        self._attn_layers = []
        for i, layer in enumerate(model.model.layers):
            self._attn_layers.append((i, layer.self_attn))
        self.num_layers = len(self._attn_layers)

        attn_impl = getattr(model.config, "_attn_implementation", None)
        if attn_impl and attn_impl != "eager":
            warnings.warn(
                f"attn_implementation={attn_impl!r} does not return attention weights. "
                f"Load model with attn_implementation='eager' for GAR measurement.",
                stacklevel=2,
            )

    def _make_hook(self, layer_idx):
        def hook_fn(module, input, output):
            # Qwen2Attention.forward returns (attn_output, attn_weights, past_key_value)
            if isinstance(output, tuple) and len(output) > 1 and output[1] is not None:
                attn_w = output[1]  # (bsz, num_heads, q_len, kv_len)
                if self.measure_only:
                    attn_w = attn_w.detach().float()
                else:
                    attn_w = attn_w.float()
                self._attention_weights[layer_idx] = attn_w
        return hook_fn

    @contextmanager
    def measure(self):
        """Caller must pass output_attentions=True to model.forward() inside this context."""
        self._attention_weights = {}
        self._hooks = []
        self._active = True

        try:
            for layer_idx, attn_module in self._attn_layers:
                h = attn_module.register_forward_hook(self._make_hook(layer_idx))
                self._hooks.append(h)
            yield self
        finally:
            for h in self._hooks:
                h.remove()
            self._hooks = []
            self._active = False

    def compute_gar(self, goal_positions, query_positions):
        if not self._attention_weights:
            raise RuntimeError("No attention data collected. Run model forward inside measure() context with output_attentions=True.")

        if not goal_positions or not query_positions:
            return {
                "gar_per_query": [],
                "gar_per_layer": np.zeros((self.num_layers, 0)),
                "gar_per_head": np.zeros((self.num_layers, 0, 0)),
                "mean_gar": 0.0,
            }

        goal_idx = torch.tensor(goal_positions, dtype=torch.long)
        query_idx = torch.tensor(query_positions, dtype=torch.long)
        num_queries = len(query_positions)

        sorted_layers = sorted(self._attention_weights.keys())
        num_layers = len(sorted_layers)

        first_weights = self._attention_weights[sorted_layers[0]]
        num_heads = first_weights.shape[1]

        gar_per_head = np.zeros((num_layers, num_heads, num_queries))

        for li, layer_idx in enumerate(sorted_layers):
            attn_w = self._attention_weights[layer_idx]
            # batch_size=1 assumption
            w = attn_w[0]  # (num_heads, seq_len, seq_len)

            # w[:, i, j] = attention from token i to token j (post-softmax, post-RoPE)
            goal_attn = w[:, query_idx, :][:, :, goal_idx]  # (num_heads, num_queries, num_goals)
            gar_values = goal_attn.sum(dim=-1)  # (num_heads, num_queries)

            gar_per_head[li] = gar_values.detach().cpu().numpy()

            if self.measure_only:
                self._attention_weights[layer_idx] = None

        gar_per_layer = gar_per_head.mean(axis=1)
        gar_per_query = gar_per_layer.mean(axis=0).tolist()
        mean_gar = float(np.mean(gar_per_query)) if gar_per_query else 0.0

        return {
            "gar_per_query": gar_per_query,
            "gar_per_layer": gar_per_layer,
            "gar_per_head": gar_per_head,
            "mean_gar": mean_gar,
        }

    def compute_gar_differentiable(self, goal_positions, query_positions):
        if not self._attention_weights:
            raise RuntimeError("No attention data collected.")

        if self.measure_only:
            raise RuntimeError("measure_only=True, cannot compute differentiable GAR. Set measure_only=False.")

        if not goal_positions or not query_positions:
            return torch.tensor(0.0, requires_grad=True)

        goal_idx = torch.tensor(goal_positions, dtype=torch.long)
        query_idx = torch.tensor(query_positions, dtype=torch.long)

        sorted_layers = sorted(k for k, v in self._attention_weights.items() if v is not None)
        all_gar = []

        for layer_idx in sorted_layers:
            attn_w = self._attention_weights[layer_idx]
            # batch_size=1 assumption
            w = attn_w[0]  # (num_heads, seq_len, seq_len)
            goal_attn = w[:, query_idx, :][:, :, goal_idx]
            gar_layer = goal_attn.sum(dim=-1).mean()
            all_gar.append(gar_layer)

        # Phase 2 TODO: if manual RoPE needed for differentiable path, implement here
        return torch.stack(all_gar).mean()


def compute_gar_loss(gar_per_turn, epsilon=0.02):
    if len(gar_per_turn) < 2:
        if isinstance(gar_per_turn[0], torch.Tensor):
            return torch.tensor(0.0, device=gar_per_turn[0].device, requires_grad=True)
        return torch.tensor(0.0, requires_grad=True)

    loss = torch.tensor(0.0)
    if isinstance(gar_per_turn[0], torch.Tensor):
        loss = torch.tensor(0.0, device=gar_per_turn[0].device)

    for i in range(1, len(gar_per_turn)):
        prev = gar_per_turn[i - 1]
        curr = gar_per_turn[i]
        if not isinstance(prev, torch.Tensor):
            prev = torch.tensor(prev, dtype=torch.float32)
        if not isinstance(curr, torch.Tensor):
            curr = torch.tensor(curr, dtype=torch.float32)
        drop = prev - curr - epsilon
        loss = loss + F.relu(drop)

    return loss

import torch
import torch.nn as nn
from transformers import AutoModelForCausalLM, AutoTokenizer

from config import (
    MODEL_NAME,
    LORA_RANK,
    GATE_HIDDEN_DIM,
    MAX_TURN_DISTANCE,
    TURN_EMBED_DIM,
)


class TurnEmbedding(nn.Module):

    def __init__(self):
        super().__init__()
        half_dim = TURN_EMBED_DIM // 2
        num_buckets = MAX_TURN_DISTANCE + 1
        self.distance_embed = nn.Embedding(num_buckets, half_dim)
        self.index_embed = nn.Embedding(num_buckets, half_dim)

    def forward(self, turn_distance, turn_index):
        td = turn_distance.clamp(0, MAX_TURN_DISTANCE)
        ti = turn_index.clamp(0, MAX_TURN_DISTANCE)
        return torch.cat([self.distance_embed(td), self.index_embed(ti)], dim=-1)


class GateNetwork(nn.Module):

    def __init__(self, hidden_dim, turn_embedding, init_bias=5.0):
        super().__init__()
        self.down_proj = nn.Linear(hidden_dim, LORA_RANK, bias=False)
        self.turn_embedding = turn_embedding
        self.fc1 = nn.Linear(LORA_RANK + TURN_EMBED_DIM, GATE_HIDDEN_DIM)
        self.fc2 = nn.Linear(GATE_HIDDEN_DIM, 1)
        self.fc2.bias.data.fill_(init_bias)

    def forward(self, hidden_state, turn_features):
        down = self.down_proj(hidden_state)
        turn_emb = self.turn_embedding(
            turn_features["turn_distance"],
            turn_features["turn_index"],
        )
        while turn_emb.dim() < down.dim():
            turn_emb = turn_emb.unsqueeze(0)
        if turn_emb.shape[0] == 1 and down.shape[0] > 1:
            turn_emb = turn_emb.expand(down.shape[0], -1, -1)
        combined = torch.cat([down, turn_emb], dim=-1)
        return torch.sigmoid(self.fc2(torch.relu(self.fc1(combined))))


class UniformGateNetwork(nn.Module):

    def __init__(self, hidden_dim, init_bias=5.0):
        super().__init__()
        input_dim = LORA_RANK + TURN_EMBED_DIM
        self.down_proj = nn.Linear(hidden_dim, input_dim, bias=False)
        self.fc1 = nn.Linear(input_dim, GATE_HIDDEN_DIM)
        self.fc2 = nn.Linear(GATE_HIDDEN_DIM, 1)
        self.fc2.bias.data.fill_(init_bias)

    def forward(self, hidden_state):
        down = self.down_proj(hidden_state)
        return torch.sigmoid(self.fc2(torch.relu(self.fc1(down))))


class ThreadGatedModel(nn.Module):

    def __init__(self, model_name=MODEL_NAME, gate_type="threadgate", init_bias=5.0, device_map="auto"):
        super().__init__()
        self.gate_type = gate_type

        self.base_model = AutoModelForCausalLM.from_pretrained(
            model_name, torch_dtype=torch.bfloat16, device_map=device_map,
        )
        for param in self.base_model.parameters():
            param.requires_grad = False

        hidden_dim = self.base_model.config.hidden_size
        num_layers = self.base_model.config.num_hidden_layers

        if gate_type == "threadgate":
            self.turn_embedding = TurnEmbedding()
            self.gates = nn.ModuleList([
                GateNetwork(hidden_dim, self.turn_embedding, init_bias)
                for _ in range(num_layers)
            ])
        else:
            self.gates = nn.ModuleList([
                UniformGateNetwork(hidden_dim, init_bias)
                for _ in range(num_layers)
            ])

        for i, layer in enumerate(self.base_model.model.layers):
            device = next(layer.parameters()).device
            self.gates[i].to(device=device, dtype=torch.bfloat16)
        if gate_type == "threadgate":
            device = next(self.base_model.model.layers[0].parameters()).device
            self.turn_embedding.to(device=device, dtype=torch.bfloat16)

        self._gate_values = {}
        self._current_turn_features = None

        self._hooks = []
        for i, layer in enumerate(self.base_model.model.layers):
            self._hooks.append(layer.register_forward_hook(self._make_hook(i)))

    def _make_hook(self, layer_idx):
        def hook(module, input, output):
            layer_input = input[0]
            layer_output = output[0]

            if self.gate_type == "threadgate":
                gate = self.gates[layer_idx](layer_input, self._current_turn_features)
            else:
                gate = self.gates[layer_idx](layer_input)

            f_x = layer_output - layer_input
            gated = layer_input + gate * f_x
            self._gate_values[layer_idx] = gate.detach()
            return (gated,) + output[1:]

        return hook

    def forward(self, input_ids, attention_mask=None, labels=None, turn_features=None):
        if self.gate_type == "threadgate" and turn_features is not None:
            device = next(self.base_model.model.layers[0].parameters()).device
            self._current_turn_features = {
                k: v.to(device) if isinstance(v, torch.Tensor) else v
                for k, v in turn_features.items()
            }
        else:
            self._current_turn_features = None

        outputs = self.base_model(
            input_ids=input_ids,
            attention_mask=attention_mask,
            labels=labels,
        )
        self._current_turn_features = None
        return outputs

    def get_gate_values(self):
        return dict(self._gate_values)

    def trainable_parameters(self):
        for name, param in self.named_parameters():
            if param.requires_grad:
                yield name, param

    def count_parameters(self):
        total = sum(p.numel() for p in self.parameters())
        trainable = sum(p.numel() for p in self.parameters() if p.requires_grad)
        ratio = trainable / total if total > 0 else 0.0
        return total, trainable, ratio


def create_model(gate_type="threadgate", init_bias=5.0, device_map="auto"):
    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)
    model = ThreadGatedModel(MODEL_NAME, gate_type, init_bias, device_map)
    return model, tokenizer

